import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Part 26 — Release & Deployment Strategies","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_26_Release_Deployment.md","filePath":"todo/study_plan/parts/Part_26_Release_Deployment.md"}'),o={name:"todo/study_plan/parts/Part_26_Release_Deployment.md"};function i(n,t,s,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="part-26-—-release-deployment-strategies" tabindex="-1">Part 26 — Release &amp; Deployment Strategies <a class="header-anchor" href="#part-26-—-release-deployment-strategies" aria-label="Permalink to &quot;Part 26 — Release &amp; Deployment Strategies&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Light touch — pass through during overflow days. <strong>Budget: ~1-2 hrs (overflow slot).</strong></p></blockquote><h2 id="_26-release-deployment-strategies-—-topic-inventory" tabindex="-1">26 Release &amp; Deployment Strategies — topic inventory <a class="header-anchor" href="#_26-release-deployment-strategies-—-topic-inventory" aria-label="Permalink to &quot;26 Release &amp; Deployment Strategies — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Blue-green deployment — atomic traffic switch</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 22 deployments)</td></tr><tr><td>2</td><td>Canary release — small % first, gradual rollout</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>Rolling deployment — replace instances gradually</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>4</td><td>Feature flags / toggles — release ≠ launch</td><td>🔴 💼 🎯</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: simple feature flag via Spring <code>@ConfigurationProperties</code> + conditional bean; flip flag, reload app, observe behavior change (15 min)</td></tr><tr><td>5</td><td>Backward-compatible API changes — add fields, never remove or rename</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>Backward-compatible DB changes — expand / contract (add → migrate → switch → remove)</td><td>🔴 💼 🎯</td><td>D</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: walk through renaming <code>username → user_name</code> via expand-contract (add new col, dual-write, backfill, switch reads, drop old) on paper (30 min)</td></tr><tr><td>7</td><td>Rollback strategy for every change (incl. data migrations — hardest)</td><td>🔴 💼 🎯</td><td>D</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Dark launches — code deployed but disabled</td><td>🟠 💼 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Shadow traffic — mirror prod to new service silently to compare</td><td>🟠 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>Trunk-based development vs GitFlow</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>Semantic versioning</td><td>🟠 💼</td><td>L</td><td>30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>Database migration tools — Flyway, Liquibase (idempotent migrations)</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: Flyway migration <code>V1__init.sql</code> + <code>V2__add_email_col.sql</code> running on Spring Boot startup (15 min)</td></tr><tr><td>13</td><td>Online schema change — gh-ost, pt-online-schema-change (MySQL)</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>Multi-version compatibility (rolling deploy implies N and N+1 coexist)</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>15</td><td>Feature flag platforms — LaunchDarkly, Unleash, Statsig</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>16</td><td>Kill switches as deploy guardrails</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>17</td><td>DORA metrics — deploy frequency, lead time, MTTR, change failure rate</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>18</td><td>Artifact management — Nexus, JFrog Artifactory, ECR</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>19</td><td>Hot-fix workflow</td><td>🟢</td><td>M</td><td>30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~12.5 hrs</td><td>~1.15 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~24.5 hrs</td><td>~2.25 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡 + 🟢)</td><td>~25.75 hrs</td><td>~2.35 wk</td><td></td></tr></tbody></table><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Walk through expand-contract for renaming a DB column. <ul><li><strong>Why asked:</strong> Senior-canonical safe migration. Steps: (1) Add new column <code>user_name</code>. (2) Deploy code that writes to BOTH old and new (dual-write). (3) Backfill new from old. (4) Switch reads to new. (5) Deploy code that only writes new. (6) Drop old column. Each step is reversible. Total: 4-5 deploys. Slow but safe.</li></ul></li><li><strong>Q:</strong> Feature flags — when do they earn complexity? <ul><li><strong>Why asked:</strong> Modern release-launch decoupling. Worth it when: (1) you want to deploy ahead of launch (testing in prod with safety), (2) you need per-user / per-tenant rollout (KYC partners), (3) you want kill switches for fast rollback without redeploy, (4) you do A/B testing on real traffic.</li></ul></li><li><strong>Q:</strong> Canary release — what gates promotion to next %? <ul><li><strong>Why asked:</strong> Operational depth. Metric gates: error rate, latency p99, business KPIs (verification success rate). Watch a window (10-30 min) at each stage. Auto-rollback if regression. Manual promotion + auto-rollback is more common than fully-auto promotion. Document the metrics + thresholds.</li></ul></li><li><strong>Q:</strong> Rolling deploy of 10 instances. Instance 1 is on new code, instance 2 on old code. They share a Redis cache. What can go wrong? <ul><li><strong>Why asked:</strong> Multi-version compatibility. New code may write Redis values in incompatible format (different JSON schema). Old code reads, errors. Fix: backward-compatible serialization for at least one version overlap. Or: use separate cache keys per version.</li></ul></li><li><strong>Q:</strong> Your team has 1 deploy/quarter. DORA metrics — what&#39;s wrong? <ul><li><strong>Why asked:</strong> SRE maturity. Low deploy frequency correlates with high blast radius per deploy (big bang releases). Aim for high deploy frequency + small batch sizes + automated rollback. DORA elite: multiple deploys per day, MTTR &lt; 1 hour.</li></ul></li><li><strong>Q:</strong> Walk through the rollback of a data migration that&#39;s halfway done. <ul><li><strong>Why asked:</strong> Hardest case. Data migrations often have no clean rollback — once you&#39;ve transformed 5M rows, you can&#39;t un-transform without re-applying inverse logic. Mitigations: (1) expand-contract makes rollback = &quot;undo the latest step&quot;, (2) shadow tables (keep old data, switch over), (3) accept-forward (re-run forward migration once issue is fixed), (4) point-in-time DB restore (drastic, last resort).</li></ul></li><li><strong>Q:</strong> Trunk-based development vs GitFlow — when each? <ul><li><strong>Why asked:</strong> Modern team practice. Trunk-based: short-lived feature branches (or commit directly to main), CI gates, feature flags for incomplete work. Right for high-velocity teams + automated testing. GitFlow: long-lived develop/release branches, complex merge ceremony. Older pattern, slower throughput. Most modern teams pick trunk.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your feature flag platform has 99.9% uptime. Your service depends on it for every request. What&#39;s your fallback? <ul><li><strong>Gotcha:</strong> Single-point-of-failure on flag platform. Each request blocking on flag eval = LF availability impacts your service. Mitigations: (1) SDK with local cache + last-known-good values, (2) bounded blocking time + default values on timeout, (3) periodic flag refresh, async from request path.</li></ul></li><li><strong>Q:</strong> You did blue-green with a stateful service (long-lived DB connections). Switched green→blue. Half the users got errors. Why? <ul><li><strong>Gotcha:</strong> In-flight requests. The atomic switch doesn&#39;t drain existing connections gracefully. Fix: (1) tell LB to drain green (stop accepting new, keep existing), (2) wait for in-flight to complete (configurable grace, typically 30-60s), (3) THEN cut new traffic to blue, (4) terminate green. Modern LBs (ALB, K8s Services) handle this with connection draining settings.</li></ul></li><li><strong>Q:</strong> You added a non-null column to a 10M-row table during deploy. The deploy took 20 minutes and the app was unavailable. What&#39;s wrong? <ul><li><strong>Gotcha:</strong> Adding NOT NULL column with default value requires updating every existing row → table lock or long migration. Right: (1) add nullable column first, (2) backfill in batches, (3) only then add NOT NULL constraint after all rows have value. Or use online schema change tools (gh-ost) that do it without locking.</li></ul></li><li><strong>Q:</strong> Your kill switch is in code: <code>if (KILL_SWITCH_ENABLED) return; ...</code>. The bug is in the code before the kill switch. The switch doesn&#39;t save you. Why? <ul><li><strong>Gotcha:</strong> Kill switch placement. If the bug is in code BEFORE the switch check, you&#39;ve already failed. Kill switches need to be EARLY in the request path — ideally first-line in the controller / at the API gateway. Defense in depth: also have a circuit breaker that can disable a downstream call.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Expand-contract DB migration end-to-end</strong> (~3 hrs row 6) — the senior-canonical safe migration. Walk through it for a real KYC schema change.</li><li><strong>Rollback strategy for data migrations</strong> (~2.5 hrs row 7) — hardest case. Document patterns: shadow tables, accept-forward, PITR.</li><li><strong>Feature flag architecture for KYC platform</strong> (~2.5 hrs row 4) — kill switches per partner, gradual rollouts for new verification logic, A/B testing on UX.</li><li><strong>Canary release + metric gating</strong> (~2 hrs row 2) — define which metrics gate promotion, the watch window, auto-rollback policy.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up release exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Flyway migration with rollback</strong> (~45 min) — write <code>V1__create_users.sql</code>, <code>V2__add_email.sql</code>. Then write <code>U2__remove_email.sql</code> rollback. Apply, then rollback. Verify state.</li><li><strong>Feature flag with local-cache SDK</strong> (~60 min) — Spring Boot + a flag client (or a simple in-memory one). Flag values served from local cache + refreshed every 30s. Service still works if flag platform is down (uses last-known-good).</li><li><strong>Expand-contract DB column rename walkthrough</strong> (~60 min) — write each migration step as a SQL script + corresponding code change. Document the 5-step process for a real example.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Canary deploy with metric gating</strong> (~75 min) — K8s deployment with two ReplicaSets (canary + stable). Argo Rollouts or Flagger config. Define metric gates (error rate, latency). Promote canary based on metrics. Auto-rollback on regression.</li><li><strong>Multi-version compatibility test</strong> (~90 min) — deploy old + new versions side-by-side. Send requests to both. Use a feature flag to route 50/50. Verify both versions handle each other&#39;s data correctly (e.g., new version reads old serialized cache, old version reads new).</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5.5 hrs</strong></td><td><strong>~0.5 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~60 min for Part 26 across 3 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Expand-contract — 5 steps?</strong> A. (1) Add new column. (2) Dual-write old + new. (3) Backfill new from old. (4) Switch reads to new. (5) Stop writing old + drop. Each step is reversible.</p><p><strong>Q. Blue-green vs canary — one-line distinction.</strong> A. Blue-green: atomic switch between two identical envs. Canary: gradual traffic shift (1% → ... → 100%) with metric gates. Blue-green is fast rollback; canary is risk reduction.</p><p><strong>Q. DORA metrics?</strong> A. Deploy frequency (how often deploys happen), Lead time (commit-to-deploy time), MTTR (time to recover from incident), Change failure rate (% of deploys causing prod issues). Elite teams: multiple deploys/day, &lt;1 hr MTTR.</p><p><strong>Q. Feature flag earns complexity when?</strong> A. Decouple deploy from launch, per-user/tenant rollout, kill-switch capability, A/B testing on real traffic.</p><p><strong>Q. Rolling deploy gotcha — multi-version?</strong> A. Old + new instances coexist during rollout. Both must handle each other&#39;s data (cache format, message schema, DB schema). Plan for N + N+1 compatibility.</p><p><strong>Q. Rollback of data migration — hardest case why?</strong> A. Data transformation is often not invertible. Mitigations: expand-contract (rollback per step), shadow tables, accept-forward (fix the bug + roll forward), point-in-time restore (last resort).</p>',28)])])}const u=e(o,[["render",i]]);export{g as __pageData,u as default};
